def new_regressor(M, C, G, parameters):
    n = M.shape[0]
    q = sym.symbols('q0:' + str(n), real=True)
    qdot = sym.symbols('q(0:' + str(n) + ')dot', real=True)
    qddot = sym.symbols('q(0:' + str(n) + ')ddot', real=True)
    qrdot = sym.symbols('qr(0:' + str(n) + ')dot', real=True)
    qrddot = sym.symbols('qr(0:' + str(n) + ')ddot', real=True)
    tau = M @ sym.Matrix(qrddot) + C @ sym.Matrix(qrdot) + G

    combinations = get_parameter_combinations(tau, parameters, 6)
    Y, ordered_combs, tau = get_jacobian_with_dummies(tau, combinations)
    return Y, tau, ordered_combs

def get_parameter_combinations(tau, parameters, n):
    polynomials = set()
    symbols = list(parameters.keys())
    for i in range(n):
        polynomials = polynomials.union(set(sym.Poly(tau[i], symbols).monoms()))

    combinations = []
    for poly in polynomials:
        monom = 1
        for i, degree in enumerate(poly):
            monom *= symbols[i] ** degree
        combinations.append(monom)

    return combinations

def get_parameter_combinations_new(tau, parameters, n):
    # Ensure we are working with SymPy Symbol objects
    # and maintain a consistent order
    symbols = [sym.Symbol(s) if isinstance(s, str) else s for s in parameters.keys()]
    polynomials = set()
    for i in range(n):
        # .monoms() returns a list of exponent tuples, e.g., (1, 0, 2)
        poly_obj = sym.Poly(tau[i], symbols)
        polynomials.update(poly_obj.monoms())
    combinations = []
    for exponents in polynomials:
        # sym.Mul.from_args is more efficient for building products
        term = sym.Mul(*[s ** d for s, d in zip(symbols, exponents)])
        combinations.append(term)
    return combinations


def get_jacobian_with_dummies(tau, combinations):
    # 1. Sort by complexity (Highest degree/most symbols first)
    # This ensures L6**2 * m5 is replaced BEFORE L6 or m5
    ordered_combs = sorted(combinations, key=lambda x: sym.total_degree(x),
                           reverse=True)

    # 2. Create the dummy symbols (d1, d2...)
    d_symbols = sym.symbols(f"d1:{len(ordered_combs) + 1}")

    # 3. Use structural replacement
    # Using a dictionary with .replace(query, value) is more robust
    # than .subs() because it matches the specific expression tree node.
    tau_substituted = tau.expand()
    for monom, d in zip(ordered_combs, d_symbols):
        tau_substituted = tau_substituted.subs(monom, d)

    # 4. NOW the Jacobian works because d1, d2... are atomic symbols
    # This gives you your Y matrix
    Y = tau_substituted.jacobian(d_symbols)

    return Y, ordered_combs, tau_substituted
def verify_regressor(Y: sym.Matrix, theta: sym.Matrix,
                     M: sym.Matrix, C: sym.Matrix, G: sym.Matrix) -> bool:
    """Verify if Y*theta = M*qddot + C*qdot + G, by substituting random joint values

    Args:
        Y (sym.Matrix): Regressor matrix
        theta (sym.Matrix): Robot parameters
        M (sym.Matrix): Inertia matrix
        C (sym.Matrix): Coriolis and centripetal matrix
        G (sym.Matrix): Gravity vector

    Returns:
        bool: True if the regressor is correct, False otherwise
    """
    n = M.shape[0]
    q = sym.symbols('q0:'+str(n))
    qdot = sym.symbols('q(0:'+str(n)+')dot')
    qddot = sym.symbols('q(0:'+str(n)+')ddot')

    # verify with random q, qdot values
    q_val = np.random.rand(n)
    qdot_val = np.random.rand(n)
    qddot_val = np.random.rand(n)
    q_map = {q[i]: q_val[i] for i in range(n)}
    qdot_map = {qdot[i]: qdot_val[i] for i in range(n)}
    qddot_map = {qddot[i]: qddot_val[i] for i in range(n)}
    joint_maps = {**q_map, **qdot_map, **qddot_map}

    M_val = M.subs(joint_maps)
    C_val = C.subs(joint_maps)
    G_val = G.subs(joint_maps)
    Y_val = Y.subs(joint_maps)
    theta_val = theta.subs(joint_maps)

    left = Y_val * theta_val
    right = M_val @ qddot_val + C_val @ qdot_val + np.reshape(G_val, (3))
    left = np.reshape(left, (3))
    threshhold = 0.1
    residual = (left - right).astype(float)
    if np.linalg.norm(residual) > threshhold:
        return False
    return True
